    if (exposureTimeNs <= 0L) return "1/0s"
    val seconds = exposureTimeNs / 1_000_000_000.0
    return if (seconds >= 1.0) {
        "${"%.1f".format(seconds).trimEnd('0').trimEnd('.')}s"
    } else {
        val denominator = (1.0 / seconds).roundToInt()
        if (denominator >= 1) "1/${denominator}s" else "<1s"
    }
