        new_board[r2][c2]=piece
    new_board[r1][c1]=''
    # castling rook
    if piece.upper()=='K' and abs(c2-c1)==2:
        if c2>c1:
            new_board[r1][c1+1]=new_board[r1][c1+3]
            new_board[r1][c1+3]=''
        else:
            new_board[r1][c1-1]=new_board[r1][c1-4]
            new_board[r1][c1-4]=''
    return new_board

def moves_to_uci(moves):
    res=[]
    for r1,c1,r2,c2,prom in moves:
        s=f"{sq_name(r1,c1)}{sq_name(r2,c2)}"
        if prom:
            s+=prom.lower()
        res.append(s)
    return res

def legal_moves(fen):
    board,active,castling,ep=parse_fen(fen)
    pseudo=generate_pseudo_moves(board,active,castling,ep)
    legal=[]
    for mv in pseudo:
        nb=make_move(board,mv)
        if not is_king_in_check(nb,active):
            legal.append(mv)
    return moves_to_uci(legal)

def perft(fen,depth):
    # simple perft using pseudo moves for counting, not fully legal
    # keep original signature
    board,active,castling,ep=parse_fen(fen)
    def rec(b,colour,cr,ep_sq,d):
        if d==0:
            return 1
        moves=generate_pseudo_moves(b,colour,cr,ep_sq)
        total=0
        for mv in moves:
            nb=make_move(b,mv)
            total+=rec(nb,'b' if colour=='w' else 'w',cr,ep_sq,d-1)
        return total
    return rec(board,active,castling,ep,depth)
